// "Feeds": one item per news feed in the client's config, for "Fetch feed".
// A client with no feeds still gets one item, so the run goes on with no reports.
const run = $("Input").first().json;
const feeds = run.client?.news_feeds ?? [];
return feeds.length ? feeds.map((json) => ({ json })) : [{ json: { id: "none", kind: "none", label: "no feeds", url: "" } }];

// "Recent reports": reads every feed "Fetch feed" got, keeps items from this story's week on,
// and adds the newest 12 to the run as `reports`. Write decides which, if any, fit the story.
// A feed that fails is noted in `feeds_checked` and skipped; news never stops a run.
const run = $("Input").first().json;
const feeds = $("Feeds").all().map((i) => i.json);
const answers = $input.all().map((i) => i.json);

const strip = (s) => String(s ?? "")
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, "$1")
  .replace(/<[^>]+>/g, " ")
  .replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&#39;|&rsquo;|&lsquo;/g, "'").replace(/&quot;|&ldquo;|&rdquo;/g, '"').replace(/&lt;/g, "<").replace(/&gt;/g, ">")
  .replace(/\s+/g, " ").trim();
const tag = (xml, t) => { const m = xml.match(new RegExp(`<${t}[^>]*>([\\s\\S]*?)</${t}>`)); return m ? strip(m[1]) : ""; };
const iso = (d) => { const t = new Date(d); return Number.isNaN(t.getTime()) ? null : t.toISOString(); };
const clip = (s, n) => (s.length > n ? s.slice(0, n).replace(/\s+\S*$/, "") + "..." : s);
const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);

const read = {
  rss: (text) => [...text.matchAll(/<item>([\s\S]*?)<\/item>/g)].map(([, x]) => ({
    title: tag(x, "title"), summary: clip(tag(x, "description"), 300), url: tag(x, "link"), published: iso(tag(x, "pubDate")),
  })),
  weather_alerts: (text) => {
    const seen = new Set();
    return (JSON.parse(text).features ?? []).map((f) => f.properties).filter((p) => {
      const key = `${p.alert_name_en}|${p.feature_name_en}`;
      if (seen.has(key) || new Date(p.expiration_datetime) < new Date()) return false;
      seen.add(key);
      return true;
    }).map((p) => ({
      title: `${cap(p.alert_name_en)} for ${p.feature_name_en}`,
      summary: clip(strip(p.alert_text_en), 400),
      url: "https://weather.gc.ca/warnings/index_e.html",
      published: iso(p.publication_datetime),
    }));
  },
  open511: (text) => (JSON.parse(text).events ?? []).map((e) => ({
    title: clip(strip(e.description), 120),
    summary: clip(strip(e.description), 300),
    url: "https://www.drivebc.ca/",
    published: iso(e.updated ?? e.created),
  })),
};

// From the start of the story's week, with half a day to spare for time zones.
const since = new Date(new Date(`${run.story.week_start}T00:00:00Z`).getTime() - 12 * 36e5);
const found = [];
const feeds_checked = [];
feeds.forEach((f, i) => {
  if (f.kind === "none") return;
  const a = answers[i] ?? {};
  if (typeof a.data !== "string" || !a.data) {
    feeds_checked.push({ feed: f.label, ok: false, reason: a.error?.message ?? "no answer" });
    return;
  }
  let items;
  try {
    if (!read[f.kind]) throw new Error(`unknown feed kind ${f.kind}`);
    items = read[f.kind](a.data);
  } catch (e) {
    feeds_checked.push({ feed: f.label, ok: false, reason: `could not read it: ${e.message}` });
    return;
  }
  const recent = items.filter((x) => x.title && (!x.published || new Date(x.published) >= since));
  feeds_checked.push({ feed: f.label, ok: true, items: items.length, recent: recent.length });
  for (const x of recent) found.push({ source: f.source_note, feed: f.id, ...x });
});
found.sort((a, b) => String(b.published ?? "").localeCompare(String(a.published ?? "")));
const reports = found.slice(0, 12).map((r, k) => ({ id: `r${k + 1}`, ...r }));
return [{ json: { ...run, ok: true, reports, feeds_checked } }];

// "Search request": the web search Claude runs for a story someone asked for in Slack. Uses the
// Anthropic web search tool (basic variant, so every finding comes back with the exact words it
// cites from the page). Settings come from the client's config (web_search).
const run = $input.first().json;
const ws = run.client?.web_search || {};
const s = run.story;
const ask = {
  asked_in_slack: run.request?.text || null,
  topic: s.topic,
  neighbourhood: s.area || null,
  city: ws.location?.city || null,
  data_week: `${s.week_start} to ${s.week_ending}`,
  data_says: `${s.this_week} ${s.unit} this week against an average of ${s.avg_prev_8_weeks} a week over the 8 weeks before`,
};
const tool = { type: "web_search_20250305", name: "web_search", max_uses: ws.max_searches || 3 };
if (ws.location) tool.user_location = { type: "approximate", ...ws.location };
if (ws.blocked_domains?.length) tool.blocked_domains = ws.blocked_domains;
return [{ json: { ...run, search_body: {
  model: "claude-sonnet-5-5",
  max_tokens: 4000,
  output_config: { effort: "low" },
  system: "You research context for a short local news video. Someone asked for this story in Slack, and the numbers already come from open data. Your job is to find what recent reporting and official sources say about the same topic, so the editor can see it and the script can mention it.\n\nSearch the web for recent news or official information about the topic, in the client's city and, if one is given, the neighbourhood. Prefer local news outlets and official sources such as the city, the province and Environment Canada. Only reporting from the last 30 days matters.\n\nThen write 2 to 5 findings, one sentence each, each backed by a citation to the page it came from. Add nothing the sources do not say, and never guess at causes. If you find nothing about the topic in the place asked about, say so in one sentence instead.\n",
  tools: [tool],
  messages: [{ role: "user", content: JSON.stringify(ask, null, 2) }],
} } }];

// "Web sources": turns the web search into sources for Write, the editor and the trace.
// Every source is a page Claude cited, kept with the exact words it was cited for (`summary`),
// so the number guard and the editor check against the page's own words, not Claude's.
// They join the feed reports as ids w1, w2...; a search that fails is noted and skipped.
const run = $("Search request").first().json;
const { search_body, ...rest } = run;
const res = $input.first().json;
const ws = run.client?.web_search || {};
const blocks = Array.isArray(res.content) ? res.content : [];
const clip = (s, n) => (s.length > n ? s.slice(0, n).replace(/\s+\S*$/, "") + "..." : s);
const host = (u) => { try { return new URL(u).hostname.replace(/^www\./, ""); } catch { return ""; } };

const queries = blocks.filter((b) => b.type === "server_tool_use" && b.name === "web_search").map((b) => b.input?.query).filter(Boolean);
const results = new Map(); // url -> what the search returned for it
for (const b of blocks) {
  if (b.type !== "web_search_tool_result") continue;
  if (!Array.isArray(b.content)) continue; // an error object, such as max_uses_exceeded
  for (const r of b.content) if (r.url && !results.has(r.url)) results.set(r.url, { title: r.title, page_age: r.page_age ?? null });
}

// Each cited sentence becomes a finding; each page it cites becomes (or adds to) a source.
const sources = new Map();
const findings = [];
for (const b of blocks) {
  if (b.type !== "text" || !b.citations?.length) continue;
  const claim = b.text.trim();
  const urls = [];
  for (const c of b.citations) {
    if (c.type !== "web_search_result_location" || !c.url) continue;
    const s = sources.get(c.url) || { url: c.url, title: c.title || results.get(c.url)?.title || host(c.url), quotes: [], claims: [] };
    const q = String(c.cited_text || "").trim();
    if (q && !s.quotes.includes(q)) s.quotes.push(q);
    if (claim && !s.claims.includes(claim)) s.claims.push(claim);
    sources.set(c.url, s);
    urls.push(c.url);
  }
  if (urls.length) findings.push({ claim, urls });
}
const summaryText = blocks.filter((b) => b.type === "text").map((b) => b.text).join("").trim();

const web = [...sources.values()].slice(0, ws.max_sources || 6).map((s, k) => ({
  id: `w${k + 1}`,
  source: host(s.url),
  feed: "web",
  title: s.title,
  summary: clip(s.quotes.join(" ... "), 600),
  claims: s.claims,
  url: s.url,
  published: null,
  page_age: results.get(s.url)?.page_age ?? null,
}));

const failed = res.error || res.type === "error" || !blocks.length;
const searches = res.usage?.server_tool_use?.web_search_requests ?? queries.length;
const web_search = {
  model: res.model ?? null,
  usage: res.usage ?? null,
  stop_reason: res.stop_reason ?? null,
  searches,
  queries,
  results_seen: results.size,
  sources_kept: web.length,
  findings,
  summary: failed ? null : clip(summaryText, 600),
  error: failed ? (res.error?.message || res.error || "no answer") : null,
};
const checked = failed
  ? { feed: "Web search", ok: false, reason: String(web_search.error) }
  : { feed: `Web search: ${queries.join("; ") || "no query"}`, ok: true, items: results.size, recent: web.length };
return [{ json: { ...rest, reports: [...(rest.reports || []), ...web], feeds_checked: [...(rest.feeds_checked || []), checked], web_search } }];
